const body = $input.first().json.body;
const phone = body.phone || '';
const name = body.name || 'Customer';
const msgId = body.id || '';
const msgTime = body.msg_time || Date.now();
const payload = body.payload || {};
const text = payload.text || '';

return [{
  json: {
    phone,
    name,
    msgId,
    msgTime,
    text,
    type: 'USER_MESSAGE',
    savedAt: new Date().toISOString()
  }
}];

const DEBOUNCE_MS = 8000;

const src = $('Extract Message Details').first().json;
const phone = src.phone;
const name = src.name || 'Customer';
const text = src.text;
const msgId = src.msgId;
const msgTime = src.msgTime;

if (!phone) throw new Error('Store Message in Session: phone missing');

const gs = $getWorkflowStaticData('global');
if (!gs.sessions) gs.sessions = {};

const now = Date.now();

if (!gs.sessions[phone]) {
    gs.sessions[phone] = { phone, name, messages: [], executionId: null, lockTime: 0, processed: false };
}

const session = gs.sessions[phone];

session.messages.push({ text, msgId, msgTime, addedAt: now });
session.name = name;
session.lockTime = now;
session.processed = false;
session.executionId = $execution.id;

return [{
    json: {
          phone, name, text, msgId, msgTime,
          executionId: $execution.id,
          messagesCount: session.messages.length,
          debounceMs: DEBOUNCE_MS
    }
}];
    }
}]
}

const item = $input.first().json;
const phone = item.phone;
const name = item.name || 'Customer';

const workflowStaticData = $getWorkflowStaticData('global');
const session = workflowStaticData.sessions && workflowStaticData.sessions[phone];

if (!session) {
  return [{ json: { phone, name, shouldProcess: false, reason: 'no_session', messages: [] } }];
}

if (session.processed) {
  return [{ json: { phone, name, shouldProcess: false, reason: 'already_processed', messages: [] } }];
}

if (session.executionId !== $execution.id) {
  return [{ json: { phone, name, shouldProcess: false, reason: 'newer_execution_wins', messages: [] } }];
}

// Extra safety: if the session lock is very recent (another message came in < 5 seconds ago), skip
const timeSinceLock = Date.now() - (session.lockTime || 0);
if (timeSinceLock < 5000 && session.executionId !== $execution.id) {
  return [{ json: { phone, name, shouldProcess: false, reason: 'lock_too_recent', messages: [] } }];
}

// Mark as processed immediately to prevent any race condition
workflowStaticData.sessions[phone].processed = true;

const messages = session.messages || [];

// Clean up session
delete workflowStaticData.sessions[phone];

return [{ json: { phone, name, shouldProcess: true, messages, reason: 'process' } }];

const procData = $('Should We Process Now?').first().json;

const phone = procData.phone;
const name = procData.name || 'Customer';
const newMessages = procData.messages || [];

// Conversation history from Firestore
let historyItems = [];
try { historyItems = $('Fetch Conversation History').all(); } catch (e) { historyItems = []; }

const history = [];
for (const item of historyItems) {
  const d = item.json;
  if (!d.type) continue;
  if (d.type === 'USER_MESSAGE') history.push({ role: 'user', content: d.text || '', time: d.msgTime || d.savedAt });
  else if (d.type === 'AI_REPLY') history.push({ role: 'assistant', content: d.text || '', time: d.savedAt });
}

// Sort by time to ensure chronological order
history.sort((a, b) => {
  const timeA = new Date(a.time || 0).getTime();
  const timeB = new Date(b.time || 0).getTime();
  return timeA - timeB;
});

const recentHistory = history.slice(-20);

// FIX: Join with newline instead of space to keep messages separate
const newMsgText = newMessages.map(m => m.text).join('\n');

const isFirstContact = !history.some(h => h.role === 'assistant');

// Office hours check IST (9:30 AM - 6:30 PM)
const nowUTC = new Date();
const istTime = new Date(nowUTC.getTime() + (5.5 * 60 * 60 * 1000));
const totalMinutes = istTime.getUTCHours() * 60 + istTime.getUTCMinutes();
const isOfficeHours = totalMinutes >= (9 * 60 + 30) && totalMinutes < (18 * 60 + 30);

// Read system prompt from Google Docs
let basePrompt = 'You are Ananya, a Health Expert at SehatUP.';

try {
  const docData = $('Get a document').first().json;
  if (docData && docData.body && docData.body.content && Array.isArray(docData.body.content)) {
    const extracted = docData.body.content
      .map(b => b.paragraph && b.paragraph.elements
        ? b.paragraph.elements.map(e => (e.textRun && e.textRun.content) ? e.textRun.content : '').join('')
        : '')
      .join('').trim();
    if (extracted) basePrompt = extracted;
  }
} catch (e) {
  console.log('Could not read Google Doc, using default prompt:', e.message);
}

// Build conversation context string for better greeting detection
const conversationContext = recentHistory.map(h => h.content).join(' ').toLowerCase();
const hasGreetingInHistory = conversationContext.includes('main ananya hoon') || conversationContext.includes('health expert at sehatup');

// Inject dynamic variables with stronger anti-greeting guard
const systemPrompt = basePrompt
  + '\n\nCONTEXT:\nFirst contact: ' + (isFirstContact ? 'YES' : 'NO')
  + '\nOffice hours: ' + (isOfficeHours ? 'OPEN' : 'CLOSED')
  + '\nCustomer name: ' + name
  + '\nGreeting already sent: ' + (hasGreetingInHistory ? 'YES' : 'NO')
  + '\n\nCRITICAL ANTI-SPAM RULES:\n'
  + '1. If "Greeting already sent: YES", NEVER send greeting again. Jump straight to answering the question.\n'
  + '2. If conversation history shows you already introduced yourself as Ananya, do NOT repeat introduction.\n'
  + '3. Only greet if: First contact: YES AND Greeting already sent: NO AND no assistant messages in history.\n'
  + '4. For follow-up questions, respond directly without any greeting or introduction.';

const messages = [
  { role: 'system', content: systemPrompt },
  ...recentHistory.map(h => ({ role: h.role, content: h.content })),
  { role: 'user', content: newMsgText }
];

return [{ json: { phone, name, messages, newMsgText, isFirstContact, hasGreetingInHistory, systemPromptLength: systemPrompt.length } }];

const groqResponse = $input.first().json;
const aiText = groqResponse.candidates?.[0]?.content?.parts?.[0]?.text || 'Sorry, kuch problem aa gayi. Please dobara try karein.';

const buildData = $('Build AI Prompt').first().json || {};

// Fallback chain: trust the upstream source-of-truth nodes, not just one ref
let phone = buildData.phone;
if (!phone) {
  try { phone = $('Should We Process Now?').first().json.phone; } catch (e) {}
}

// Fail loud with context instead of a cryptic .replace crash
if (!phone) {
  throw new Error(
    'Extract AI Response: phone missing. buildData=' + JSON.stringify(buildData)
  );
}

const name = buildData.name || 'Customer';
const newMsgText = buildData.newMsgText || '';
const docId = phone.replace('+', '');

return [{
  json: {
    phone,
    name,
    lastAiReply: aiText,
    lastUserMessage: newMsgText,
    docId,
    lastUpdated: new Date().toISOString()
  }
}];

const item = $input.first().json;
return [{
  json: {
    phone: item.phone,
    type: 'AI_REPLY',
    text: item.lastAiReply,
    savedAt: new Date().toISOString()
  }
}];

